// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: from address (sender), uint v, and an array of recipient addresses
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // admissible domain: tos must be non-empty because function requires it
        vm.assume(tos.length > 0);

        // deploy a minimal helper that implements transferFrom(address,address,uint256)
        // which simply returns (doesn't revert) so the call succeeds
        Receiver r = new Receiver();

        // use the helper's address as the callee for each recipient in tos by overwriting
        // but to keep fuzzing meaningful, we call c.transfer with the helper address
        // and the provided tos array (tos can be any addresses, but c forwards to r regardless)

        // call c.transfer and capture whether it completes (it should)
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: when the call completes (ok == true), the reference
        // implementation always returns true. We assert that the call completed (ok==true)
        // implies the returned value would be true. Because we cannot call the mutant here,
        // we assert that the call completed (ok) — the mutant violates the return value by
        // returning false while the call still completes. To make this assertion observable
        // and compatible with the requirement of a single assertTrue reading c, we assert
        // that the call did not revert (ok == true). The reference C always completes
        // successfully with our helper; the mutant would also complete but return false,
        // which is a behavioral difference the fuzzer can find by comparing returns off-chain.

        // Single required assertion reading c's behavior: whether the external call completed.
        assertTrue(ok);
    }
}

// Helper that accepts the low-level call with selector transferFrom(address,address,uint256)
contract Receiver {
    // respond to the selector and do nothing (success)
    fallback() external payable {
        // accept any call and succeed
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We need a simple callee that accepts the low-level call and returns true to mimic a successful transferFrom
    contract Callee {
        // matches selector transferFrom(address,address,uint256)
        function transferFrom(address, address, uint) external pure returns (bool) {
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // Fuzz parameters: from (caller singer), address of callee contract, two arbitrary target addresses and a value and length.
    // We cannot fuzz addresses to point to a contract, so we will deploy a helper Callee and pass its address; still fuzz the other params.
    function testFuzz_property(address from, address a1, address a2, uint256 v) public {
        // 1. keep addresses wide but avoid zero-address for from and targets to be reasonable
        vm.assume(from != address(0));
        vm.assume(a1 != address(0));
        vm.assume(a2 != address(0));
        // 2. deploy helper callee and build _tos array with at least one element to exercise non-empty path
        Callee helper = new Callee();
        address calleeAddr = address(helper);
        address[] memory tos = new address[](2);
        tos[0] = a1;
        tos[1] = a2;

        // 3. Call transfer via try/catch to capture non-revert completion and returned boolean from the reference implementation.
        // The reference contract's rule: for any non-empty _tos, transfer returns true (and does not revert because helper returns true to each call).
        bool okRef;
        bool retRef;
        try c.transfer(from, calleeAddr, tos, v) returns (bool r) {
            okRef = true;
            retRef = r;
        } catch {
            okRef = false;
            retRef = false;
        }

        // Single assertion: when the call completes (okRef == true) the returned value must be true.
        // This property holds for the reference C for all inputs (because it returns true after loop for any non-empty _tos).
        // The one-statement mutant that inverts the final return will make this assertion fail for some inputs (non-empty _tos),
        // which the fuzzer can find.
        assertTrue(!(okRef && retRef == false));
    }
}

// Minimal helper declared outside of InvMutTest scope is not required here since we declared Callee inside the test contract.
// (No additional helpers.)
